/**
 * Generates TypeScript types from the JSON Schemas so the compile-time types and the
 * runtime validator can never drift (single source of truth = schemas/*.schema.json).
 * CI re-runs this and fails if the committed output differs.
 */
import { compileFromFile } from "json-schema-to-typescript";
import { writeFileSync } from "node:fs";

const banner = `/* eslint-disable */
/**
 * AUTO-GENERATED by scripts/generate-types.ts from schemas/*.schema.json.
 * DO NOT EDIT BY HAND. Run: npm run gen:types
 */
`;

const targets = ["property", "sponsor", "property-sponsor"];
let out = banner;
for (const name of targets) {
  const ts = await compileFromFile(`schemas/${name}.schema.json`, {
    cwd: "schemas",
    bannerComment: "",
    additionalProperties: false,
    unreachableDefinitions: false,
    maxItems: -1,
  });
  out += `\n${ts}`;
}
// Each schema re-declares shared aliases; de-duplicate identical top-level declarations.
const seen = new Set<string>();
const blocks = out.split(/\n(?=(?:\/\*\*[\s\S]*?\*\/\n)?export (?:type|interface) )/);
const deduped = blocks.filter((b) => {
  const m = b.match(/export (?:type|interface) (\w+)/);
  if (!m) return true;
  if (seen.has(m[1])) return false;
  seen.add(m[1]);
  return true;
});
writeFileSync("src/contract/types.generated.ts", deduped.join("\n").replace(/\n{3,}/g, "\n\n"));
console.log("wrote src/contract/types.generated.ts");
